create or replace function public.server_activate_product(p_user_id uuid,p_public_code text,p_activation_secret text) returns uuid language plpgsql security definer set search_path='' as $$declare v_product private.products;v_activated_at timestamptz:=now();begin if p_user_id is null then raise exception 'invalid';end if;select * into v_product from private.products where public_code=p_public_code for update;if not found or v_product.status<>'available' or extensions.crypt(p_activation_secret,v_product.activation_secret_hash)<>v_product.activation_secret_hash then raise exception 'invalid';end if;update private.products set owner_id=p_user_id,status='active',activated_at=v_activated_at,activation_secret_hash=encode(extensions.gen_random_bytes(32),'hex'),updated_at=v_activated_at where id=v_product.id;insert into public.user_products(product_id,user_id,public_code,status,activated_at,updated_at) values(v_product.id,p_user_id,v_product.public_code,'active',v_activated_at,v_activated_at);return v_product.id;end$$;
revoke all on function public.server_activate_product(uuid,text,text) from public,anon,authenticated;grant execute on function public.server_activate_product(uuid,text,text) to service_role;
